static inline int test_bit(int nr, const volatile unsigned long *vaddr) /* <=== test_bit */ 
{
	return (vaddr[nr >> 5] & (1UL << (nr & 31))) != 0;
}

static int tty_change_softcar(struct tty_struct *tty, int arg) /* <=== tty_change_softcar */ 
{
	int ret = 0;
	int bit = arg ? CLOCAL : 0;
	struct ktermios old;

	down_write(&tty->termios_rwsem);
	old = tty->termios;
	tty->termios.c_cflag &= ~CLOCAL;
	tty->termios.c_cflag |= bit;
	if (tty->ops->set_termios)
		tty->ops->set_termios(tty, &old);
	if (C_CLOCAL(tty) != bit)
		ret = -EINVAL;
	up_write(&tty->termios_rwsem);
	return ret;
}

int down_read(struct rw_semaphore *sem) /* <=== down_read */ 
{
	return perf_singlethreaded ? 0 : pthread_rwlock_rdlock(&sem->lock);
}

static inline void clear_bit(unsigned nr, volatile unsigned long *addr) /* <=== clear_bit */ 
